<?php require '../config/db.php';
$where=[]; $p=[]; $types=''; if(!empty($_GET['from'])){$where[]='DATE(transaction_date)>=?';$p[]=$_GET['from'];$types.='s';} if(!empty($_GET['to'])){$where[]='DATE(transaction_date)<=?';$p[]=$_GET['to'];$types.='s';} if(!empty($_GET['type'])){$where[]='transaction_type=?';$p[]=$_GET['type'];$types.='s';} if(!empty($_GET['q'])){$where[]='(item_code LIKE ? OR item_description LIKE ? OR pic_receiver LIKE ?)';$like='%'.$_GET['q'].'%';$p[]=$like;$p[]=$like;$p[]=$like;$types.='sss';}
$sql='SELECT transaction_date,transaction_type,item_code,item_description,quantity,serial_number,location,uom,pic_receiver,remarks FROM inventory_transactions '.($where?'WHERE '.implode(' AND ',$where):'').' ORDER BY transaction_date DESC'; $stmt=$conn->prepare($sql); if($p)$stmt->bind_param($types,...$p); $stmt->execute(); $rs=$stmt->get_result();
header('Content-Type: text/csv'); header('Content-Disposition: attachment; filename="filtered_report.csv"'); $out=fopen('php://output','w'); fputcsv($out,['Date When','What/Action','Item Code','Description','Qty','Serial','Location','UOM','PIC','Remarks']); while($r=$rs->fetch_assoc()) fputcsv($out,$r); fclose($out);
